    vi.mocked(repo.listAuthUsers).mockResolvedValue([]);
    vi.mocked(supabaseAdmin.auth.admin.inviteUserByEmail).mockResolvedValue({ data: { user: {} }, error: null } as InviteUserByEmailResult);

