import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import type { ChangeLogEntry } from '@asohav/shared';
import { appendChangeLog } from './repo.js';

vi.mock('./supabase.js', () => ({
  supabaseAdmin: {
    from: vi.fn(),
  },
}));

describe('appendChangeLog', () => {
  const originalEnv = { ...process.env };
  let supabaseAdmin: any;

  beforeEach(() => {
    vi.clearAllMocks();
    // Re-import the module to get fresh mocks
    vi.resetModules();
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const { supabaseAdmin: mockedSupabaseAdmin } = require('./supabase.js');
    supabaseAdmin = mockedSupabaseAdmin;
  });

  afterEach(() => {
    process.env = { ...originalEnv };
    vi.unstubAllGlobals();
  });

  it('inserts a changelog entry without an explicit id, letting the database generate it', async () => {
    const mockInsert = vi.fn().mockResolvedValue({ data: null, error: null });
    supabaseAdmin.from.mockReturnValue({
      insert: mockInsert,
    });

    const entry: Omit<ChangeLogEntry, 'Id' | 'At'> = {
      Who: 'test@example.com',
      Action: 'create',
      Collection: 'characters',
      ObjectId: 'char-123',
      ObjectName: 'Test Character',
      Before: null,
      After: { Name: 'Test Character', Pronouns: 'they/them' },
    };

    await appendChangeLog(entry);

    expect(mockInsert).toHaveBeenCalledWith({
      at: expect.any(String),
      who: entry.Who,
      action: entry.Action,
      collection: entry.Collection,
      object_id: entry.ObjectId,
      object_name: entry.ObjectName,
      before: entry.Before,
      after: entry.After,
    });

    // Verify that no 'id' field was passed to the insert
    const insertCallArgs = mockInsert.mock.calls[0][0];
    expect(insertCallArgs).not.toHaveProperty('id');
  });

  it('propagates errors from the database insert', async () => {
    const mockInsert = vi.fn().mockResolvedValue({ data: null, error: new Error('Database error') });
    supabaseAdmin.from.mockReturnValue({
      insert: mockInsert,
    });

    const entry: Omit<ChangeLogEntry, 'Id' | 'At'> = {
      Who: 'test@example.com',
      Action: 'update',
      Collection: 'characters',
      ObjectId: 'char-123',
      ObjectName: 'Test Character',
      Before: { Name: 'Old Name' },
      After: { Name: 'New Name' },
    };

    await expect(appendChangeLog(entry)).rejects.toThrow('Database error');
  });
});

